#[test]
fn match_python_custom_cipher_vectors() {
    for vector in VECTORS {
        let cipher = riak::v3::RiakV3Cipher::from_words(vector.key);
        let sealed = cipher
            .seal(&vector.nonce, vector.aad, vector.plaintext)
            .unwrap();
        assert_eq!(sealed, vector.sealed, "seal mismatch: {}", vector.name);
        assert_eq!(
            cipher.open(&vector.nonce, vector.aad, vector.sealed).unwrap(),
            vector.plaintext,
            "open mismatch: {}",
            vector.name
        );
    }
}
